import{_ as a,o as e,c as r,a3 as d}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"状态所有权与 Store 边界","description":"","frontmatter":{"title":"状态所有权与 Store 边界","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/data/state-management.md","filePath":"frontend/decisions/data/state-management.md","lastUpdated":1785589115000}'),o={name:"frontend/decisions/data/state-management.md"};function i(l,t,h,n,s,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="状态所有权与-store-边界" tabindex="-1">状态所有权与 Store 边界 <a class="header-anchor" href="#状态所有权与-store-边界" aria-label="Permalink to &quot;状态所有权与 Store 边界&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>状态管理的首要决定不是选 Pinia、Redux 或其他 Store，而是确定每份状态由谁拥有、生命周期多长、是否能从其他来源重新计算。把 URL、服务端缓存、表单草稿和弹窗开关全部放进全局 Store，会制造多个事实来源和难以解释的同步规则。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>应用增长后，共享状态确实会出现，但“多个组件用到”不等于“全局持久化”。状态越容易被任何代码读写，变化来源越难追踪；状态过度局部，又会产生层层传递和重复请求。</p><p>基础建模参见<a href="/frontend/guide/core/application/state-modeling">状态建模</a>、<a href="/frontend/guide/core/application/server-state-cache">服务端状态与缓存</a>和<a href="/frontend/guide/core/vue/pinia">Pinia</a>。本章只决定所有权和 Store 引入边界。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-所有权硬约束" tabindex="-1">2.1 所有权硬约束 <a class="header-anchor" href="#_2-1-所有权硬约束" aria-label="Permalink to &quot;2.1 所有权硬约束&quot;">​</a></h3><ul><li>服务端权威数据不能因复制进 Store 就变成客户端事实来源；</li><li>可由其他状态计算的值不应独立持久化；</li><li>URL 应承载需要刷新、分享或返回恢复的导航状态；</li><li>敏感信息不得因持久化插件进入不受控存储；</li><li>跨标签页和离线写入必须定义冲突与过期规则。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较状态范围、生命周期、写入者数量、可重建性、同步复杂度、调试能力、服务端一致性、SSR 序列化和测试成本。Store API 的简短程度只是次要因素。</p><h2 id="_3-状态分类与候选所有者" tabindex="-1">3. 状态分类与候选所有者 <a class="header-anchor" href="#_3-状态分类与候选所有者" aria-label="Permalink to &quot;3. 状态分类与候选所有者&quot;">​</a></h2><h3 id="_3-1-组件局部状态" tabindex="-1">3.1 组件局部状态 <a class="header-anchor" href="#_3-1-组件局部状态" aria-label="Permalink to &quot;3.1 组件局部状态&quot;">​</a></h3><p>弹窗开关、悬停、未提交输入等只服务当前组件树，优先由组件或 composable 持有。提升到全局 Store 会延长生命周期并允许无关代码修改。</p><h3 id="_3-2-url-状态" tabindex="-1">3.2 URL 状态 <a class="header-anchor" href="#_3-2-url-状态" aria-label="Permalink to &quot;3.2 URL 状态&quot;">​</a></h3><p>搜索词、筛选、分页、选中标签等若需要复制链接、刷新恢复或浏览器前进后退，应由 URL 拥有。组件和 Store 可以读取它，但不应维护第二份独立值。</p><h3 id="_3-3-服务端状态" tabindex="-1">3.3 服务端状态 <a class="header-anchor" href="#_3-3-服务端状态" aria-label="Permalink to &quot;3.3 服务端状态&quot;">​</a></h3><p>订单、用户和库存由服务端拥有，客户端保存的是带时间和请求上下文的缓存。请求缓存工具负责去重、过期、重试和失效，普通 Store 不应重新实现一套不完整的缓存协议。</p><h3 id="_3-4-表单与工作流草稿" tabindex="-1">3.4 表单与工作流草稿 <a class="header-anchor" href="#_3-4-表单与工作流草稿" aria-label="Permalink to &quot;3.4 表单与工作流草稿&quot;">​</a></h3><p>短表单可局部管理；跨步骤、可恢复或多人编辑的草稿需要明确的草稿模型、版本和保存位置。它不是简单的“全局状态”，尤其不能在提交成功后忘记清理。</p><h3 id="_3-5-客户端领域状态" tabindex="-1">3.5 客户端领域状态 <a class="header-anchor" href="#_3-5-客户端领域状态" aria-label="Permalink to &quot;3.5 客户端领域状态&quot;">​</a></h3><p>当前租户、购物车本地操作、编辑器命令历史等跨路由且由客户端负责的状态，适合显式 Store 或状态机。Store 应按领域划分，不建立一个包揽全部模块的根对象。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态示例</th><th>推荐所有者</th><th>是否进入 Store</th><th>原因</th></tr></thead><tbody><tr><td>侧栏展开</td><td>当前布局组件</td><td>通常否</td><td>生命周期局部，可重建</td></tr><tr><td>订单筛选与页码</td><td>URL</td><td>否，或只做适配</td><td>需要分享和返回恢复</td></tr><tr><td>订单详情</td><td>服务端查询缓存</td><td>否</td><td>服务端权威，需失效和竞态处理</td></tr><tr><td>当前租户</td><td>会话/应用级 Store</td><td>是</td><td>跨路由使用，切换会驱动多个模块</td></tr><tr><td>新订单未提交草稿</td><td>表单模型；必要时持久草稿</td><td>视范围而定</td><td>有独立校验和保存生命周期</td></tr><tr><td>订单总价</td><td>从条目派生</td><td>否</td><td>避免双份事实来源</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例是 Vue 3 订单运营台。团队原计划把列表、筛选、分页、选中行、详情、当前租户和批量导出任务全部放进一个 Pinia Store。</p><p>推荐拆分所有权：</p><ul><li>筛选、排序和页码写入路由 query；</li><li>列表与详情由查询缓存管理，修改成功后按订单键失效；</li><li>当前租户进入应用级 Pinia Store，并由会话初始化；</li><li>选中行仅由列表页面 composable 持有，离开页面清空；</li><li>跨页面继续运行的导出任务进入独立任务 Store，只保存任务标识和进度，不复制导出数据；</li><li>总金额、可操作数量等值由当前数据派生。</li></ul><p>这不是“完全不用 Store”，而是把 Store 限定在客户端真正拥有且跨边界共享的状态。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>收益是每类状态有唯一事实来源，刷新和返回行为可预测，服务端缓存不再与 Pinia 手工同步。代价是团队需要理解 URL、查询缓存、表单和 Store 四种生命周期，并建立清楚的适配层。</p><p>退出某个 Store 库时，只需迁移客户端领域状态；若所有远程数据和页面细节都已进入 Store，退出成本会覆盖整个应用。</p><p>SSR 场景还需确保请求间 Store 实例隔离，只序列化允许暴露的初始状态，避免跨用户泄漏。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>不要因为两个组件读取同一值就立即创建全局 Store。</li><li>不要同时在 URL 和 Store 中维护筛选值并互相 watch。</li><li>不要把查询响应复制进 Store，再手工实现过期和取消。</li><li>不要持久化访问令牌、完整用户对象或可由会话重建的敏感状态。</li><li>状态机适合阶段和转换复杂的工作流，不必用于简单布尔开关。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>订单运营台各类状态由谁拥有</td></tr><tr><td>硬约束</td><td>URL 可分享；远程数据服务端权威；租户切换不串数据；敏感状态不持久化</td></tr><tr><td>候选</td><td>单一 Pinia Store、全部局部状态、按所有权组合</td></tr><tr><td>决定</td><td>URL + 查询缓存 + 局部 composable + 两个领域 Store</td></tr><tr><td>Store 范围</td><td>当前租户、跨页导出任务</td></tr><tr><td>明确排除</td><td>订单响应、筛选、派生总价和弹窗状态</td></tr><tr><td>验证指标</td><td>重复请求、返回恢复缺陷、状态同步缺陷、Store 字段和写入者数量</td></tr><tr><td>接受代价</td><td>多种状态容器和边界培训</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>当大量页面需要相同客户端领域状态、跨路由草稿成为正式需求、SSR 引入新的初始化约束，或同步缺陷连续增长时复查。若 Store 字段长期无人读取、写入来源超过三个或经常与 URL/服务端不一致，应缩小而不是扩大 Store。</p>',39)])])}const _=a(o,[["render",i]]);export{p as __pageData,_ as default};
